UPDATE quotes SET source = 'Communion with the Triune God, Part 1, Chapter 3 (1657)', text = 'As your great trouble is about the Father''s love, so you can no way more trouble or burden him, than by your unkindness in not believing of it.' WHERE figure_id = 14 AND text = 'The greatest sorrow and burden you can lay on the Father, the greatest unkindness you can do to him, is not to believe that he loves you.';
UPDATE quotes SET source = 'The Mortification of Sin, Chapter 14 (1656)', text = 'The Spirit is the author and finisher of our sanctification; gives new supplies and influences of grace for holiness and sanctification…' WHERE figure_id = 14 AND text = 'The Holy Spirit is the author and finisher of all grace in us, and will be so to the end.';
UPDATE quotes SET source = 'A Christian Directory, Part 2, Chapter 17 (1673)', text = 'Keep up a high esteem of time; and be every day more careful that you lose none of your time, than you are that you lose none of your gold or silver.' WHERE figure_id = 15 AND text = 'Keep up a high esteem of time and be every day more careful that you lose none of it.';
UPDATE quotes SET source = 'Book of Common Prayer, Morning Prayer (1552)', text = 'We have erred and strayed from thy ways like lost sheep. We have followed too much the devices and desires of our own hearts.' WHERE figure_id = 16 AND text = 'We have erred and strayed from thy ways like lost sheep. We have followed too much the devices and desires of our own hearts.';
UPDATE quotes SET source = 'Book of Common Prayer (1549)', text = 'Grant us therefore, gracious Lord, so to eat the flesh of thy dear Son Jesus Christ, and to drink his blood in these holy Mysteries, that we may continually dwell in him, and he in us, that our sinful bodies may be made clean by his body, and our souls washed through his most precious blood.' WHERE figure_id = 16 AND text = 'Grant us therefore, gracious Lord, so to eat the flesh of thy dear Son Jesus Christ, and to drink his blood, that our sinful bodies may be made clean by his body, and our souls washed through his most precious blood.';
UPDATE quotes SET source = 'Sermon at Nottingham (1792)', text = 'Expect great things from God; attempt great things for God.' WHERE figure_id = 18 AND text = 'Expect great things from God; attempt great things for God.';
UPDATE quotes SET source = 'The Knowledge of the Holy, Chapter 1 (1961)', text = 'What comes into our minds when we think about God is the most important thing about us.' WHERE figure_id = 19 AND text = 'What comes into our minds when we think about God is the most important thing about us.';
UPDATE quotes SET source = 'The Divine Conquest (1950)', text = 'The man who would know God must give time to Him.' WHERE figure_id = 19 AND text = 'The man who would know God must give time to Him.';
UPDATE quotes SET source = 'The Root of the Righteous (1955)', text = 'It is doubtful whether God can bless a man greatly until He has hurt him deeply.' WHERE figure_id = 19 AND text = 'It is doubtful whether God can bless a man greatly until He has hurt him deeply.';
UPDATE quotes SET source = 'The Pursuit of God (1948)', text = 'Sound Bible exposition is an imperative must in the Church of the Living God. Without it no church can be a New Testament church in any strict meaning of that term.' WHERE figure_id = 19 AND text = 'Sound Bible exposition is an imperative must in the church of the living God. Without it we have no guide for the present nor hope for the future.';
UPDATE quotes SET source = 'The Mark of the Christian (1970)', text = 'Upon his authority he gives the world the right to judge whether you and I are born-again Christians on the basis of our observable love toward all Christians.' WHERE figure_id = 21 AND text = 'The mark of the Christian is the observable love for other Christians.';
UPDATE quotes SET source = 'Preaching and Preachers (1971)', text = 'The primary task of the Church is not to educate man, is not to heal him physically or psychologically, it is not to make him happy… Her primary purpose is not any of these; it is rather to put man into the right relationship with God, to reconcile man to God.' WHERE figure_id = 22 AND text = 'The primary task of the Church is not to educate man, is not to heal him physically or psychologically, it is to save his soul.';
UPDATE quotes SET source = 'The Normal Christian Life (1957)', text = 'The Blood can wash away my sins, but it cannot wash away my ''old man''. It needs the Cross to crucify me. The Blood deals with the sins, but the Cross must deal with the sinner.' WHERE figure_id = 23 AND text = 'The Cross is God''s way of dealing with our old sinful nature; by crucifying it so that the life of Christ might be expressed.';
UPDATE quotes SET source = 'The Release of the Spirit (1965)', text = 'The way of service lies in brokenness, in accepting the discipline of the Holy Spirit. The measure of your service is determined by the degree of discipline and brokenness.' WHERE figure_id = 23 AND text = 'The measure of our usefulness is the measure of our brokenness.';
UPDATE quotes SET source = 'The Spiritual Letters of Fénelon, Letters to Men, Letter 88', text = 'Tell Him all that is in your heart, as one unloads one''s heart to a dear friend of all that gives it pain or pleasure.' WHERE figure_id = 24 AND text = 'Tell God all that is in your heart, as one unloads one''s heart, its pleasures and its pains, to a dear friend.';
UPDATE quotes SET source = 'Autobiography of Madame Guyon (1720)', text = 'There seemed, indeed, to be no will left in me but thine only. My own disappeared, and no desires, tendencies or inclinations were left, but to the one sole object of whatever was most pleasing to thee…' WHERE figure_id = 25 AND text = 'I had no longer any will of my own — the will of God was the object of all my desires.';
UPDATE quotes SET source = 'The Imitation of Christ, Book I, Chapter 1 (circa 1418)', text = 'What doth it profit thee to enter into deep discussion concerning the Holy Trinity, if thou lack humility, and be thus displeasing to the Trinity?' WHERE figure_id = 26 AND text = 'What doth it profit thee to enter into deep discussion concerning the Holy Trinity, if thou lack humility?';
UPDATE quotes SET source = 'The Imitation of Christ, Book I, Chapter 2 (circa 1418)', text = 'Many words satisfy not the soul, but a good life refresheth the mind, and a pure conscience giveth great confidence towards God.' WHERE figure_id = 26 AND text = 'Many words satisfy not the soul, but a good life refresheth the mind.';
UPDATE quotes SET source = 'The Imitation of Christ, Book II, Chapter 1 (circa 1418)', text = 'The kingdom of God is within you, saith the Lord. Turn thee with all thine heart to the Lord and forsake this miserable world, and thou shalt find rest unto thy soul.' WHERE figure_id = 26 AND text = 'The kingdom of God is within you, saith the Lord. Turn thee with thy whole heart unto the Lord, and forsake this wretched world.';
UPDATE quotes SET source = 'The Imitation of Christ, Book I, Chapter 1 (circa 1418)', text = 'It is vanity to desire a long life, and to have little care for a good life.' WHERE figure_id = 26 AND text = 'It is vanity to wish for long life, and to have little care for a good life.';
UPDATE quotes SET source = 'The Imitation of Christ, Book I, Chapter 6 (circa 1418)', text = 'For true peace of heart is to be found in resisting passion, not in yielding to it.' WHERE figure_id = 26 AND text = 'True peace of heart is found only in resisting the passions, not in yielding to them.';
UPDATE quotes SET source = 'The Imitation of Christ, Book I, Chapter 2 (circa 1418)', text = 'Rest from inordinate desire of knowledge, for therein is found much distraction and deceit.' WHERE figure_id = 26 AND text = 'Above all, rest from inordinate desire of knowledge, for therein is found much distraction and deceit.';
UPDATE quotes SET source = 'The Practice of the Presence of God, Conversation 1 (published 1692)', text = 'We should establish ourselves in a sense of God''s presence, by continually conversing with Him.' WHERE figure_id = 27 AND text = 'I have found that we can establish ourselves in a sense of the presence of God by continually talking with him.';
UPDATE quotes SET source = 'The Practice of the Presence of God, Letter 5 (published 1692)', text = 'Were I a preacher, I should, above all other things, preach the practice of the presence of God.' WHERE figure_id = 27 AND text = 'Were I a preacher, I should, above all other things, preach the practice of the presence of God.';
UPDATE quotes SET source = 'The Practice of the Presence of God, Letter 4 (published 1692)', text = 'God has infinite treasure to bestow, and we take up with a little sensible devotion, which passes in a moment. Blind as we are, we hinder God.' WHERE figure_id = 27 AND text = 'God has infinite treasure to bestow, and we take up with a little sensible devotion, which passes in a moment. Blind as we are, we hinder God.';
UPDATE quotes SET source = 'The Practice of the Presence of God, Letter 2 (published 1692)', text = 'I make it my business only to persevere in His holy presence, wherein I keep myself by a simple attention, and a general fond regard to God.' WHERE figure_id = 27 AND text = 'I make it my business only to persevere in His holy presence, wherein I keep myself by a simple attention, and a general fond regard to God.';
UPDATE quotes SET source = 'The Practice of the Presence of God, Letter 6 (published 1692)', text = 'I cannot imagine how religious persons can live satisfied without the practice of the presence of God.' WHERE figure_id = 27 AND text = 'I cannot imagine how religious persons can live satisfied without the practice of the presence of God.';
UPDATE quotes SET source = 'The Practice of the Presence of God, Letter 7 (published 1692)', text = 'He requires no great matters of us; a little remembrance of Him from time to time; a little adoration.' WHERE figure_id = 27 AND text = 'God requires no great matters of us; a little remembrance of him from time to time, a little adoration.';
UPDATE quotes SET source = 'The Practice of the Presence of God, Letter 8 (published 1692)', text = 'I do not advise you to use multiplicity of words in prayer: many words and long discourses being often the occasions of wandering.' WHERE figure_id = 27 AND text = 'I do not advise you to use multiplicity of words in prayer, many words and long discourses being often the occasions of wandering.';
UPDATE quotes SET source = 'Revelations of Divine Love, Chapter 68 (circa 1393)', text = 'He said not: Thou shalt not be tempested, thou shalt not be travailed, thou shalt not be afflicted; but He said: Thou shalt not be overcome.' WHERE figure_id = 28 AND text = 'He said not ''Thou shalt not be tempested, thou shalt not be travailed, thou shalt not be afflicted,'' but He said ''Thou shalt not be overcome.''';
UPDATE quotes SET source = 'Revelations of Divine Love, Chapter 19 (circa 1393)', text = 'I would have looked up from the Cross, but I durst not. For I wist well that while I beheld in the Cross I was surely-safe…' WHERE figure_id = 28 AND text = 'In this time I wanted to look beside the Cross, and I durst not; for I wist well, while I beheld in the Cross I was sure and safe from all peril.';
UPDATE quotes SET source = 'Revelations of Divine Love, Chapter 77 (circa 1393)', text = 'Our courteous Lord willeth that we should be as homely with Him as heart may think or soul may desire.' WHERE figure_id = 28 AND text = 'Our courteous Lord willeth that we should be as homely with Him as heart may think or soul may desire.';
UPDATE quotes SET source = 'Revelations of Divine Love, Chapter 41 (circa 1393)', text = 'I am Ground of thy beseeching: first it is my will that thou have it; and after, I make thee to will it; and after, I make thee to beseech it and thou beseechest it.' WHERE figure_id = 28 AND text = 'I am the Ground of thy beseeching: first it is my will that thou have it; and after, I make thee to will it; and after, I make thee to beseech it, and thou dost beseech it.';
UPDATE quotes SET source = 'Revelations of Divine Love, Chapter 86 (circa 1393)', text = 'Wouldst thou learn thy Lord''s meaning in this thing? Learn it well: Love was His meaning. Who shewed it thee? Love. What shewed He thee? Love. Wherefore shewed it He? For Love.' WHERE figure_id = 28 AND text = 'Love was His meaning. Who showed thee this? Love. What showed He thee? Love. Wherefore was it showed? For Love.';
UPDATE quotes SET source = 'Revelations of Divine Love, Chapter 5 (circa 1393)', text = 'God, of Thy Goodness, give me Thyself: for Thou art enough to me, and I may nothing ask that is less that may be full worship to Thee.' WHERE figure_id = 28 AND text = 'God, of Thy goodness, give me Thyself; for Thou art enough to me, and I may nothing ask that is less.';
UPDATE quotes SET source = 'The Ascent of Mount Carmel, Book I, Chapter 11 (circa 1579)', text = 'This is the state of a soul with particular attachments: it never can attain to the liberty of the divine union, whatever virtues it may possess.' WHERE figure_id = 29 AND text = 'The soul that is attached to anything, however much good there may be in it, will not arrive at the liberty of divine union.';
UPDATE quotes SET source = 'The Ascent of Mount Carmel, Book I, Chapter 13 (circa 1579)', text = 'That thou mayest have pleasure in everything, seek pleasure in nothing. … That thou mayest possess all things, seek to possess nothing.' WHERE figure_id = 29 AND text = 'To reach satisfaction in all, desire its possession in nothing. To come to possess all, desire the possession of nothing.';
UPDATE quotes SET source = 'Sayings of Light and Love (circa 1585)', text = 'The soul that walks in love neither tires others nor grows tired.' WHERE figure_id = 29 AND text = 'The soul that walks in love neither tires others nor grows tired.';
UPDATE quotes SET source = 'Spiritual Canticle, Stanza 1 (circa 1578)', text = 'Where hast Thou hidden Thyself, And abandoned me in my groaning, O my Beloved?' WHERE figure_id = 29 AND text = 'Where hast thou hidden thyself, and left me to my groaning, O Beloved?';
UPDATE quotes SET source = 'Sayings of Light and Love (circa 1585)', text = 'Seek by reading and you will find by meditating; cry in prayer and the door will be opened in contemplation.' WHERE figure_id = 29 AND text = 'Seek in reading and thou wilt find in meditating; knock in prayer and it will be opened to thee in contemplation.';
UPDATE quotes SET source = 'Sayings of Light and Love (circa 1585)', text = 'The Father uttered one Word; that Word is His Son: and He utters Him for ever in everlasting silence, and in silence the soul has to hear It.' WHERE figure_id = 29 AND text = 'The Father spoke one Word, which was His Son, and this Word He speaks always in eternal silence, and in silence must it be heard by the soul.';
UPDATE quotes SET source = 'Interior Castle, Mansion 1, Chapter 1 (1577)', text = 'It is no small misfortune and disgrace that, through our own fault, we neither understand our nature nor our origin.' WHERE figure_id = 30 AND text = 'It is no small pity, and should cause us no little shame, that through our own fault we do not understand ourselves, or know who we are.';
UPDATE quotes SET source = 'Interior Castle, Mansion 4, Chapter 1 (1577)', text = '…it is not so essential to think much as to love much: therefore you must practise whatever most excites you to this.' WHERE figure_id = 30 AND text = 'The important thing is not to think much but to love much, and so do that which best stirs you to love.';
UPDATE quotes SET source = 'The Life of Teresa of Jesus, Chapter 8 (1565)', text = '…mental prayer is nothing else, in my opinion, but being on terms of friendship with God, frequently conversing in secret with Him Who, we know, loves us.' WHERE figure_id = 30 AND text = 'Prayer is nothing else than an intimate sharing between friends; it means taking time frequently to be alone with Him who we know loves us.';
UPDATE quotes SET source = 'Poems, Nada te turbe', text = 'Let nothing disturb thee, Nothing affright thee; All things are passing; God never changeth; Patient endurance Attaineth to all things; Who God possesseth In nothing is wanting; Alone God sufficeth.' WHERE figure_id = 30 AND text = 'Let nothing disturb you, let nothing frighten you, all things are passing away: God never changes.';
UPDATE quotes SET source = 'The Foundations, Chapter 5 (1576)', text = '…the good of the soul does not consist in its thinking much, but in its loving much.' WHERE figure_id = 30 AND text = 'The soul is not nourished by much thinking but by much loving.';
UPDATE quotes SET source = 'The Life of Teresa of Jesus, Chapter 8 (1565)', text = 'Prayer is the door to those great graces which our Lord bestowed upon me.' WHERE figure_id = 30 AND text = 'Prayer is the door to those graces which God showers upon us.';
UPDATE quotes SET source = 'On Loving God, Chapter 1 (circa 1135)', text = 'You want me to tell you why God is to be loved and how much. I answer, the reason for loving God is God Himself; and the measure of love due to Him is immeasurable love.' WHERE figure_id = 31 AND text = 'You wish me to tell you why God is to be loved and how much. I answer: the reason for loving God is God Himself.';
UPDATE quotes SET source = 'Sermons on the Song of Songs, Sermon 84 (circa 1153)', text = 'You would not seek Him at all, O soul, nor love Him at all, if you had not been first sought and first loved.' WHERE figure_id = 31 AND text = 'Thou wouldst not seek Me if thou hadst not found Me.';
UPDATE quotes SET source = 'On Consideration, Book II, Chapter 6 (circa 1150)', text = 'Learn the lesson that, if you are to do the work of a prophet, what you want is not a sceptre, but a hoe.' WHERE figure_id = 31 AND text = 'Learn the lesson that, if you are to do the work of a prophet, what you need is not a scepter but a hoe.';
UPDATE quotes SET source = 'On Grace and Free Choice, Chapter 1 (circa 1128)', text = 'Take away free will and there remaineth nothing to be saved; take away grace and there is no means whereby it can be saved.' WHERE figure_id = 31 AND text = 'Take away free will and there is nothing to save. Take away grace and there is no means of saving.';
UPDATE quotes SET source = 'Sermons on the Song of Songs, Sermon 18 (circa 1136)', text = 'If, then, you are wise, you will show yourself rather as a reservoir than as a canal.' WHERE figure_id = 31 AND text = 'The man who is wise, therefore, will see his life as more like a reservoir than a canal.';
UPDATE quotes SET source = 'The Canticle of the Sun (1224)', text = 'Praise be to Thee, my Lord, with all Thy creatures, Especially to my worshipful brother sun…' WHERE figure_id = 32 AND text = 'Praised be You, my Lord, with all Your creatures, especially Sir Brother Sun.';
UPDATE quotes SET source = 'The Earlier Rule (Regula non bullata), Chapter 17 (1221)', text = 'Let all the brothers preach by their works.' WHERE figure_id = 32 AND text = 'All the friars must preach by their deeds.';
UPDATE quotes SET source = 'The Admonitions, Admonition 27 (circa 1220)', text = 'Where there is charity and wisdom there is neither fear nor ignorance.' WHERE figure_id = 32 AND text = 'Where there is charity and wisdom, there is neither fear nor ignorance.';
UPDATE quotes SET source = 'The Admonitions, Admonition 25 (circa 1220)', text = 'Blessed is that brother who would love his brother as much when he is ill and not able to assist him as he loves him when he is well and able to assist him.' WHERE figure_id = 32 AND text = 'Blessed is the servant who loves his brother as much when he is sick and useless as when he is well and can be of service to him.';
UPDATE quotes SET source = 'The Canticle of the Sun (1224)', text = 'Praised be my Lord for our sister, the bodily death, From the which no living man can flee.' WHERE figure_id = 32 AND text = 'Praised be You, my Lord, through our Sister Bodily Death, from whom no living man can escape.';
UPDATE quotes SET source = 'The Earlier Rule (Regula non bullata), Chapter 17 (1221)', text = 'And let us refer all good to the Lord God most High and Supreme; let us acknowledge that all good belongs to Him…' WHERE figure_id = 32 AND text = 'Let us refer all good to the most high and supreme Lord God, and acknowledge that all good belongs to Him.';
UPDATE quotes SET source = 'The Testament of St. Francis (1226)', text = 'And when the Lord gave me some brothers, no one showed me what I ought to do, but the Most High Himself revealed to me that I should live according to the form of the holy Gospel.' WHERE figure_id = 32 AND text = 'After the Lord gave me some brothers, no one showed me what I ought to do; but the Most High Himself revealed to me that I should live according to the form of the Holy Gospel.';
UPDATE quotes SET source = 'Abandonment to Divine Providence, Book II, Chapter 4 (published 1861)', text = '…the words God addresses you each moment—words which are not conveyed to you by means of ink and paper, but by what you have to do and suffer from moment to moment…' WHERE figure_id = 34 AND text = 'God speaks to every individual through what happens to them moment by moment.';
UPDATE quotes SET source = 'Abandonment to Divine Providence, Book II, Chapter 1 (published 1861)', text = 'Faith gives to the whole earth a heavenly aspect; faith transports, enraptures the heart, and raises it above the things of this earth to converse with the blessed.' WHERE figure_id = 34 AND text = 'Faith transforms the earth into a paradise. By it our hearts are raised with the joy of our nearness to heaven.';
UPDATE quotes SET source = 'Abandonment to Divine Providence, Book II, Chapter 3 (published 1861)', text = 'The present moment is always filled with infinite treasures: it contains more than you are capable of receiving.' WHERE figure_id = 34 AND text = 'The present moment is always full of infinite treasure; it contains far more than you have the capacity to hold.';
UPDATE quotes SET source = 'The Fire of Love, Book I, Chapter 17 (circa 1343)', text = 'What is love but the transforming of desire into the thing loved?' WHERE figure_id = 35 AND text = 'What is love, but a transformation into the beloved?';
UPDATE quotes SET source = 'Confessions, Book X, Chapter 27 (397 AD)', text = 'Too late loved I Thee, O Thou Beauty of ancient days, yet ever new! too late I loved Thee!' WHERE figure_id = 36 AND text = 'Late have I loved Thee, O Beauty so ancient and so new; late have I loved Thee!';
UPDATE quotes SET source = 'Confessions, Book VIII, Chapter 7 (397 AD)', text = 'Give me chastity and continency, only not yet.' WHERE figure_id = 36 AND text = 'Give me chastity and continence, but not yet.';
UPDATE quotes SET source = 'On the Incarnation, Chapter 20 (circa 318 AD)', text = 'And so it was that two marvels came to pass at once, that the death of all was accomplished in the Lord''s body, and that death and corruption were wholly done away by reason of the Word that was united with it.' WHERE figure_id = 37 AND text = 'The death of all was consummated in the Lord''s body; yet, because the Word was in it, death and corruption were in the same act utterly abolished.';
UPDATE quotes SET source = 'On the Incarnation, Chapter 20 (circa 318 AD)', text = 'He next offered up His sacrifice also on behalf of all … to show Himself more powerful even than death, displaying His own body incorruptible, as first-fruits of the resurrection of all.' WHERE figure_id = 37 AND text = 'The resurrection of the body has been made certain by the Resurrection of Christ.';
UPDATE quotes SET source = 'Homilies on First Corinthians, Homily 32 (circa 392 AD)', text = 'Let us consider, if it were every where in abundance, how great benefits would ensue: how there were no need then of laws, or tribunals or punishments … since if all loved and were beloved, no man would injure another.' WHERE figure_id = 38 AND text = 'The love of Christ constrains us: where love is, no laws are needed; where love is absent, no laws are of any avail.';
UPDATE quotes SET source = 'Homilies on Matthew, Homily 50 (circa 390 AD)', text = 'Would you do honor to Christ''s body? Neglect Him not when naked; do not while here you honor Him with silken garments, neglect Him perishing without of cold and nakedness.' WHERE figure_id = 38 AND text = 'Do you wish to honour the body of Christ? Do not ignore him when he is naked.';
UPDATE quotes SET source = 'On Prayer, Chapter 8 (circa 233 AD)', text = 'That benefit accrues to him who prays rightly … follows, I consider, in many ways: It is, first of all, surely in every sense a spiritual advantage to him who is intent upon prayer, in the very composure of prayer to present himself to God and in His presence to speak to Him.' WHERE figure_id = 39 AND text = 'Prayer is of great profit to the one who prays, and it is not without result when offered to God with a pure heart.';
UPDATE quotes SET source = 'Letter to the Philippians, Chapter 3 (circa 110 AD)', text = 'For neither I, nor any other such one, can come up to the wisdom of the blessed and glorified Paul.' WHERE figure_id = 40 AND text = 'For neither I nor anyone like me can follow the wisdom of the blessed and glorious Paul.';
UPDATE quotes SET source = 'Martyrdom of Polycarp, Chapter 9 (155 AD)', text = 'Eighty and six years have I served Him, and He never did me any injury: how then can I blaspheme my King and my Saviour?' WHERE figure_id = 40 AND text = 'Eighty and six years have I served Christ, and He never did me any wrong. How then can I blaspheme my King and my Saviour?';
UPDATE quotes SET source = 'Letter to the Philippians, Chapter 12 (circa 110 AD)', text = 'Pray for all the saints. Pray also for kings, and potentates, and princes, and for those that persecute and hate you, and for the enemies of the cross, that your fruit may be manifest to all.' WHERE figure_id = 40 AND text = 'I pray for all men, and especially that they may be saved.';
UPDATE quotes SET source = 'Letter to the Romans, Chapter 4 (circa 110 AD)', text = 'I am the wheat of God, and let me be ground by the teeth of the wild beasts, that I may be found the pure bread of Christ.' WHERE figure_id = 41 AND text = 'I am God''s wheat, ground fine by the lion''s teeth to be made purest bread for Christ.';
UPDATE quotes SET source = 'Letter to the Ephesians, Chapter 15 (circa 110 AD)', text = 'It is better for a man to be silent and be [a Christian], than to talk and not to be one.' WHERE figure_id = 41 AND text = 'It is better to keep silent and be real than to talk and be unreal.';
UPDATE quotes SET source = 'Letter to the Magnesians, Chapter 13 (circa 110 AD)', text = 'Study, therefore, to be established in the doctrines of the Lord and the apostles.' WHERE figure_id = 41 AND text = 'Study, therefore, to be established in the doctrines of the Lord and the apostles.';
UPDATE quotes SET source = 'Letter to the Smyrnaeans, Chapter 6 (circa 110 AD)', text = 'Let no man deceive himself. Both the things which are in heaven, and the glorious angels, and rulers, both visible and invisible, if they believe not in the blood of Christ, shall, in consequence, incur condemnation.' WHERE figure_id = 41 AND text = 'Let no man deceive himself. Both the things which are in heaven, and the glorious angels, and rulers, both visible and invisible, if they believe not in the blood of Christ, shall, in like manner, face condemnation.';
UPDATE quotes SET source = 'Letter to the Ephesians, Chapter 7 (circa 110 AD)', text = 'There is one Physician who is possessed both of flesh and spirit; both made and not made; God existing in flesh.' WHERE figure_id = 41 AND text = 'There is one Physician who is possessed both of flesh and spirit; both made and not made; God existing in flesh.';
UPDATE quotes SET source = 'Letter to Polycarp, Chapter 6 (circa 110 AD)', text = 'Let your works be the charge assigned to you, that you may receive a worthy recompense. Be long-suffering, therefore, with one another, in meekness, as God is towards you.' WHERE figure_id = 41 AND text = 'Let your works be the charge that is preferred against you: and be ye mild in answer to their wrath.';
UPDATE quotes SET source = 'Against Heresies, Book IV, Chapter 20 (circa 180 AD)', text = 'For the glory of God is a living man; and the life of man consists in beholding God.' WHERE figure_id = 42 AND text = 'The glory of God is a human being fully alive.';
UPDATE quotes SET source = 'Against Heresies, Book IV, Chapter 5 (circa 180 AD)', text = 'God, therefore, is one and the same … who made the things of time for man, so that coming to maturity in them, he may produce the fruit of immortality; and who, through His kindness, also bestows [upon him] eternal things.' WHERE figure_id = 42 AND text = 'For He who made the things of time, He it is who effects those things which are eternal.';
UPDATE quotes SET source = 'Against Heresies, Book V, Chapter 1 (circa 180 AD)', text = 'Since the Lord thus has redeemed us through His own blood, giving His soul for our souls, and His flesh for our flesh …' WHERE figure_id = 42 AND text = 'The Lord has redeemed us by His own blood, giving His soul for our souls, His flesh for our flesh.';
UPDATE quotes SET source = 'Against Heresies, Book V, Preface (circa 180 AD)', text = 'The Word of God, our Lord Jesus Christ, who did, through His transcendent love, become what we are, that He might bring us to be even what He is Himself.' WHERE figure_id = 42 AND text = 'Christ Jesus our Lord, who did, through His transcendent love, become what we are, that He might bring us to be even what He is.';
UPDATE quotes SET source = 'Stromateis, Book I, Chapter 5 (circa 198 AD)', text = 'For philosophy is the study of wisdom, and wisdom is the knowledge of things divine and human; and their causes.' WHERE figure_id = 43 AND text = 'Knowledge is an understanding of things human and divine and their causes.';
UPDATE quotes SET source = 'Exhortation to the Greeks, Chapter 1 (circa 195 AD)', text = 'The Word of God became man, that you may learn from man how man may become God.' WHERE figure_id = 43 AND text = 'The Logos of God became man that you also may learn from man how man may become God.';
UPDATE quotes SET source = 'On the Unity of the Church, Chapter 6 (251 AD)', text = 'He can no longer have God for his Father, who has not the Church for his mother.' WHERE figure_id = 44 AND text = 'He cannot have God for his Father, who has not the Church for his mother.';
UPDATE quotes SET source = 'On Mortality, Chapter 26 (252 AD)', text = 'Let us greet the day which assigns each of us to his own home, which snatches us hence, and sets us free from the snares of the world, and restores us to paradise and the kingdom.' WHERE figure_id = 44 AND text = 'Let us embrace the day which assigns each of us to his own home, which snatches us hence, and sets us free.';
UPDATE quotes SET source = 'On Mortality, Chapter 20 (252 AD)', text = 'Our brethren who are freed from this world by the Lord''s summons are not to be lamented, since we know that they are not lost, but sent before.' WHERE figure_id = 44 AND text = 'The Christian should not grieve at the departure of those dear to him, since he knows that they are not lost but gone before.';
UPDATE quotes SET source = 'On the Unity of the Church, Chapter 14 (251 AD)', text = 'He cannot be a martyr who is not in the Church.' WHERE figure_id = 44 AND text = 'He cannot be a martyr who is not in the Church.';
UPDATE quotes SET source = 'Homilies on the Hexameron, Homily 5 (circa 378 AD)', text = 'I want creation to penetrate you with so much admiration that everywhere, wherever you may be, the least plant may bring to you the clear remembrance of the Creator.' WHERE figure_id = 45 AND text = 'I want creation to penetrate you with so much admiration that wherever you go, the least plant may bring you the clear remembrance of the Creator.';
UPDATE quotes SET source = 'The Life of Moses, Book I (circa 390 AD)', text = 'The perfection of human nature consists perhaps in its very growth in goodness.' WHERE figure_id = 46 AND text = 'The perfection of human nature consists perhaps in its very growth in goodness.';
UPDATE quotes SET source = 'The Life of Moses, Book II (circa 390 AD)', text = 'Every concept which comes from some comprehensible image by an approximate understanding and by guessing at the divine nature constitutes an idol of God and does not proclaim God.' WHERE figure_id = 46 AND text = 'Concepts create idols; only wonder comprehends anything.';
UPDATE quotes SET source = 'On the Soul and the Resurrection (circa 380 AD)', text = 'If, then, the soul is purified of every vice, it will most certainly be in the sphere of Beauty. The Deity is in very substance Beautiful; and to the Deity the soul will in its state of purity have affinity.' WHERE figure_id = 46 AND text = 'The soul, when purified, attains to the original beauty of its nature.';
UPDATE quotes SET source = 'The Life of Moses, Part I (circa 390 AD)', text = 'The one who is going to associate intimately with God must go beyond all that is visible and (lifting up his own mind, as to a mountaintop, to the invisible and incomprehensible) believe that the divine is there where the understanding does not reach.' WHERE figure_id = 46 AND text = 'He who is going to associate with God must go beyond all that is visible and lift up his mind as if to a mountaintop.';
UPDATE quotes SET source = 'Letter 101 (circa 382 AD)', text = 'For that which He has not assumed He has not healed; but that which is united to His Godhead is also saved.' WHERE figure_id = 47 AND text = 'What is not assumed is not healed; but that which is united to God is also saved.';
UPDATE quotes SET source = 'Theological Orations, Oration 28 (circa 380 AD)', text = 'It is difficult to conceive God but to define Him in words is an impossibility … But in my opinion it is impossible to express Him, and yet more impossible to conceive Him.' WHERE figure_id = 47 AND text = 'To contemplate God is the highest and most difficult of all things.';
