UPDATE quotes SET source = 'First Apology, Chapter 10 (circa 155 AD)', text = 'And we have been taught, and are convinced, and do believe, that He accepts those only who imitate the excellences which reside in Him, temperance, and justice, and philanthropy.' WHERE figure_id = 50 AND text = 'We have been taught that only they may go to God who live according to the good which He has taught.';
UPDATE quotes SET source = 'First Apology, Chapter 13 (circa 155 AD)', text = 'What sober-minded man, then, will not acknowledge that we are not atheists, worshipping as we do the Maker of this universe … whom we praise to the utmost of our power by the exercise of prayer and thanksgiving for all things wherewith we are supplied …' WHERE figure_id = 50 AND text = 'We worship the Maker of the universe, declaring Him alone to be God, and declaring that He alone is worthy of praise.';
UPDATE quotes SET source = 'Where Do We Go from Here: Chaos or Community? (1967)', text = 'Power without love is reckless and abusive, and love without power is sentimental and anemic.' WHERE figure_id = 51 AND text = 'Power without love is reckless and abusive, and love without power is sentimental and anaemic.';
UPDATE quotes SET source = 'Stride Toward Freedom (1958)', text = 'Human progress is neither automatic nor inevitable. … Every step toward the goal of justice requires sacrifice, suffering, and struggle; the tireless exertions and passionate concern of dedicated individuals.' WHERE figure_id = 51 AND text = 'Human progress is neither automatic nor inevitable. Every step toward the goal of justice requires sacrifice, suffering, and struggle.';
UPDATE quotes SET source = 'Strength to Love (1963)', text = 'The tough-minded person always examines the facts before he reaches conclusions; in short, he postjudges. The tender-minded person reaches a conclusion before he has examined the first fact; in short, he prejudges and is prejudiced.' WHERE figure_id = 51 AND text = 'The tough-minded person always examines the facts before he reaches conclusions. In short, he postulates that right and not may, that all men are created equal.';
UPDATE quotes SET source = 'Cited in Robert Isaac Wilberforce and Samuel Wilberforce, The Life of William Wilberforce, vol. 1 (1838)', text = 'God Almighty has set before me two great objects, the suppression of the slave trade and the reformation of manners.' WHERE figure_id = 52 AND text = 'God Almighty has set before me two great objects, the suppression of the slave trade and the reformation of manners.';
UPDATE quotes SET source = 'Cited in Robert Isaac Wilberforce and Samuel Wilberforce, The Life of William Wilberforce, vol. 4 (1838)', text = 'If to be feelingly alive to the sufferings of my fellow-creatures and to be warmed with the desire of relieving their distresses, is to be a fanatic, I am one of the most incurable fanatics ever permitted to be at large.' WHERE figure_id = 52 AND text = 'If to be feelingly alive to the sufferings of my fellow creatures is to be a fanatic, I am one of the most incurable fanatics ever permitted to be at large.';
UPDATE quotes SET source = 'Cited in Cobbett''s Parliamentary History of England, vol. 29 (1817)', text = 'Never, never will we desist till we have wiped away this scandal from the Christian name, released ourselves from the load of guilt, under which we at present labour, and extinguished every trace of this bloody traffic…' WHERE figure_id = 52 AND text = 'Never, never will we desist till we have wiped away this scandal from the Christian name, released ourselves from the load of guilt.';
UPDATE quotes SET source = 'A Practical View of Christianity, Chapter 4, Section 2 (1797)', text = 'This state of mind contributes … to rectify the illusions of vision … and to remove backward, and reduce to their true comparative dimensions, the objects of the present life, which are apt to fill the human eye, assuming a false magnitude from their vicinity.' WHERE figure_id = 52 AND text = 'The objects of this world fill our eyes with a false magnifying power; it is only the eye of faith that can see the eternal world in its true proportions.';
UPDATE quotes SET source = 'A Practical View of Christianity, Chapter 4, Section 1 (1797)', text = 'This is the Christian love of God! A love compounded of admiration, of preference, of hope, of trust, of joy; chastised by reverential awe, and wakeful with continual gratitude.' WHERE figure_id = 52 AND text = 'This is the Christian love of God! A love compounded of admiration, of preference, of hope, of trust, of joy: chastised by reverential awe, and wakeful with continual gratitude.';
UPDATE quotes SET source = 'A Practical View of Christianity, Chapter 7 (1797)', text = 'Ever look to him for help: your only safety consists in a deep and abiding sense of your own weakness, and in a firm reliance on his strength.' WHERE figure_id = 52 AND text = 'Ever look to him for help: your only safety consists in a deep and permanent sense of your own weakness, and in a firm reliance on his strength.';
UPDATE quotes SET source = 'Cited in Sarah Bradford, Scenes in the Life of Harriet Tubman (1869)', text = 'No one will take me back alive; I shall fight for my liberty, and when de time has come for me to go, de Lord will let dem kill me.' WHERE figure_id = 53 AND text = 'I would fight for my liberty so long as my strength lasted, and if the time came for me to go, the Lord would let them take me.';
UPDATE quotes SET source = 'Cited in Ednah Dow Cheney, "Moses," The Freedmen''s Record (March 1865)', text = 'I prayed to God to make me strong and able to fight and that''s what I''ve allers prayed for ever since.' WHERE figure_id = 53 AND text = 'I prayed to God to make me strong and able to fight, and that''s what I''ve always prayed for ever since.';
UPDATE quotes SET source = 'Ain''t I a Woman? Women''s Rights Convention, Akron, Ohio (1851)', text = 'And ar''n''t I a woman? Look at me! Look at my arm! I have plowed, and planted, and gathered into barns, and no man could head me—and ar''n''t I a woman?' WHERE figure_id = 54 AND text = 'Ain''t I a woman? Look at me! Look at my arm! I have ploughed and planted, and gathered into barns, and no man could head me! And ain''t I a woman?';
UPDATE quotes SET source = 'Narrative of Sojourner Truth, Book of Life (1884 edition)', text = 'I feel safe even in the midst of my enemies; for the truth is powerful and will prevail.' WHERE figure_id = 54 AND text = 'I feel safe even in the midst of my enemies; for the truth is powerful and will prevail.';
UPDATE quotes SET source = 'Narrative of Sojourner Truth, Book of Life (1884 edition)', text = 'When I left the house of bondage, I left everything behind. I wa''n''t goin'' to keep nothin'' of Egypt on me, an'' so I went to the Lord an'' asked him to give me a new name.' WHERE figure_id = 54 AND text = 'When I left the house of bondage I left everything behind. I wasn''t going to keep nothing of Egypt on me, and so I went to the Lord and asked him to give me a new name.';
UPDATE quotes SET source = 'No Future Without Forgiveness (1999)', text = '…when someone cannot be forgiven there is no future.' WHERE figure_id = 55 AND text = 'Without forgiveness, there is no future.';
UPDATE quotes SET source = 'God Has a Dream (2004)', text = 'My humanity is caught up and inextricably bound up in yours. I am human because I belong.' WHERE figure_id = 55 AND text = 'My humanity is bound up in yours, for we can only be human together.';
UPDATE quotes SET source = 'Cited in Tutu: The Authorised Portrait (2011)', text = 'Do your little bit of good where you are; it''s those little bits of good put together that overwhelm the world.' WHERE figure_id = 55 AND text = 'Do your little bit of good where you are; it''s those little bits of good put together that overwhelm the world.';
UPDATE quotes SET source = 'Made for Goodness (2010)', text = 'We are made for goodness by God, who is goodness itself. We are made like God. We are made for goodness.' WHERE figure_id = 55 AND text = 'We are made for goodness. We are made for love. We are made for friendliness. We are made for togetherness.';
UPDATE quotes SET source = 'What to the Slave Is the Fourth of July? (July 5, 1852)', text = 'This Fourth of July is yours, not mine. You may rejoice, I must mourn.' WHERE figure_id = 56 AND text = 'This Fourth July is yours, not mine. You may rejoice, I must mourn.';
UPDATE quotes SET source = 'The Significance of Emancipation in the West Indies, address at Canandaigua, N.Y. (August 3, 1857)', text = 'If there is no struggle there is no progress.' WHERE figure_id = 56 AND text = 'If there is no struggle, there is no progress.';
UPDATE quotes SET source = 'My Bondage and My Freedom, Chapter 10 (1855)', text = '"Very well," thought I; "knowledge unfits a child to be a slave." I instinctively assented to the proposition; and from that moment I understood the direct pathway from slavery to freedom.' WHERE figure_id = 56 AND text = 'Knowledge makes a man unfit to be a slave.';
UPDATE quotes SET source = 'Life and Times of Frederick Douglass, revised edition (1892)', text = 'No man can put a chain about the ankle of his fellow-man, without at last finding the other end of it about his own neck.' WHERE figure_id = 56 AND text = 'No man can put a chain about the ankle of his fellow man without at last finding the other end fastened about his own neck.';
UPDATE quotes SET source = 'Speech to the Young Men''s Lyceum (January 27, 1838)', text = 'Let every American, every lover of liberty, every well-wisher to his posterity swear by the blood of the Revolution never to violate in the least particular the laws of the country, and never to tolerate their violation by others.' WHERE figure_id = 57 AND text = 'Let every American, every lover of liberty, every well-wisher to his posterity, swear by the blood of the Revolution, never to violate the laws of the country.';
UPDATE quotes SET source = 'Meditation on the Divine Will (September 2, 1862)', text = 'In the present civil war it is quite possible that God''s purpose is something different from the purpose of either party…' WHERE figure_id = 57 AND text = 'In the present civil war it is quite possible that God''s purpose is something different from the purpose of either party.';
UPDATE quotes SET source = 'Clippings from My Notebook (1982)', text = 'Worry does not empty tomorrow of its sorrow, it empties today of its strength.' WHERE figure_id = 58 AND text = 'Worry does not empty tomorrow of its sorrow, it empties today of its strength.';
UPDATE quotes SET source = 'Clippings from My Notebook (1982)', text = 'I have learned in my years on earth to hold everything loosely because when I hold things tightly, God has to pry my fingers away. And that hurts.' WHERE figure_id = 58 AND text = 'Hold everything in your hands lightly, otherwise it hurts when God pries your fingers open.';
UPDATE quotes SET source = 'Tramp for the Lord (1974)', text = 'Forgiveness is an act of the will, and the will can function regardless of the temperature of the heart.' WHERE figure_id = 58 AND text = 'Forgiveness is an act of the will, and the will can function regardless of the temperature of the heart.';
UPDATE quotes SET source = 'The Hiding Place, Foreword (1971)', text = 'Every experience God gives us, every person He puts in our lives is the perfect preparation for the future that only He can see.' WHERE figure_id = 58 AND text = 'Every experience God gives us, every person He puts in our lives is the perfect preparation for a future that only He can see.';
UPDATE quotes SET source = 'Each New Day (1977)', text = 'Never be afraid to trust an unknown future to a known God.' WHERE figure_id = 58 AND text = 'Never be afraid to trust an unknown future to a known God.';
UPDATE quotes SET source = 'Clippings from My Notebook (1982)', text = 'Is prayer your steering wheel or your spare tire?' WHERE figure_id = 58 AND text = 'Is prayer your steering wheel or your spare tire?';
UPDATE quotes SET source = 'Lectures on Revivals of Religion, Lecture 1 (1835)', text = 'It is not a miracle, or dependent on a miracle, in any sense. It is a purely philosophical result of the right use of the constituted means—as much so as any other effect produced by the application of means.' WHERE figure_id = 61 AND text = 'A revival is no more a miracle than a crop of wheat. It is the result of the right use of the appropriate means.';
UPDATE quotes SET source = 'Lectures on Systematic Theology (1846)', text = 'Sanctification, then, is nothing more nor less than entire obedience, for the time being, to the moral law.' WHERE figure_id = 61 AND text = 'Sanctification is nothing more than conformity of heart and life to the revealed will of God.';
UPDATE quotes SET source = 'Letters of John Newton (compiled 1960)', text = 'Not what I ought to be, not what I might be, not what I wish or hope to be, and not what I once was, I think I can truly say with the apostle, ''By the grace of God I am what I am.''' WHERE figure_id = 62 AND text = 'I am not what I ought to be, I am not what I want to be, I am not what I hope to be in another world; but still I am not what I once was.';
UPDATE quotes SET source = 'Cited in Richard Cecil, Memoirs of the Rev. John Newton (1808)', text = 'If two angels came down from heaven to execute a divine command, and one was appointed to conduct an empire, and the other to sweep a street in it, they would feel no inclination to choose employments.' WHERE figure_id = 62 AND text = 'If two angels were sent from heaven to execute a divine command, and one was appointed to rule an empire and the other to sweep a street, they would feel no inclination to change employments.';
UPDATE quotes SET source = 'Olney Hymns, Book 1, Hymn 31 (1779)', text = 'Thou art coming to a King; large petitions with thee bring; for His grace and power are such, none can ever ask too much.' WHERE figure_id = 62 AND text = 'Thou art coming to a King; large petitions with thee bring; for His grace and power are such, none can ever ask too much.';
UPDATE quotes SET source = 'Cited in Josiah Bull, John Newton of Olney and St. Mary Woolnoth (1868)', text = 'My memory is nearly gone, but I remember two things: that I am a great sinner and that Christ is a great Saviour.' WHERE figure_id = 62 AND text = 'My memory is nearly gone, but I remember two things: that I am a great sinner and that Christ is a great Saviour.';
UPDATE quotes SET source = 'Cited in Richard Cecil, Memoirs of the Rev. John Newton (1808)', text = 'I endeavour to walk through the world as a physician goes through Bedlam: the patients make a noise, pester him with impertinence, and hinder him in his business; but he does the best he can, and so gets through.' WHERE figure_id = 62 AND text = 'I endeavour to walk through the world as a physician goes through Bedlam: the patients make a noise, pester and tease him, but he does his best for their health.';
UPDATE quotes SET source = 'The Interesting Narrative of the Life of Olaudah Equiano, Chapter 7 (1789)', text = 'Before night, I who had been a slave in the morning, trembling at the will of another, was become my own master, and completely free. I thought this was the happiest day I had ever experienced.' WHERE figure_id = 63 AND text = 'I looked upon myself as no longer a slave; and so rejoiced exceedingly.';
UPDATE quotes SET source = 'The Interesting Narrative of the Life of Olaudah Equiano, Chapter 1 (1789)', text = 'Does not slavery itself depress the mind, and extinguish all its fire and every noble sentiment?' WHERE figure_id = 63 AND text = 'Does not slavery itself depress the mind, and extinguish all its fire, and every noble sentiment?';
UPDATE quotes SET source = 'The Interesting Narrative of the Life of Olaudah Equiano, Chapter 2 (1789)', text = 'O, ye nominal Christians! might not an African ask you, learned you this from your God, who says unto you, Do unto all men as you would men should do unto you?' WHERE figure_id = 63 AND text = 'I exhort you, O ye nominal Christians! If you believe the gospel, behave agreeable to it.';
UPDATE quotes SET source = 'Jesus and the Disinherited (1949)', text = 'The masses of men live with their backs constantly against the wall. They are the poor, the disinherited, the dispossessed. What does our religion say to them?' WHERE figure_id = 64 AND text = 'The gospel of Jesus is a gospel for the poor, for the disinherited, for the dispossessed.';
UPDATE quotes SET source = 'Jesus and the Disinherited (1949)', text = 'Fear is one of the persistent hounds of hell that dog the footsteps of the poor, the dispossessed, the disinherited. There is nothing new or recent about fear…' WHERE figure_id = 64 AND text = 'Fear is the outstanding characteristic of the disinherited. There is nothing new about this. Fear and its fellowship have walked the streets of every ghetto.';
UPDATE quotes SET source = 'Dream with Me (2017)', text = 'Love will always be our final fight.' WHERE figure_id = 65 AND text = 'Love is the final fight. We''ve got to fight to love people.';
UPDATE quotes SET source = 'The Principia: Mathematical Principles of Natural Philosophy, General Scholium (1713)', text = 'This most beautiful system of the sun, planets, and comets, could only proceed from the counsel and dominion of an intelligent and powerful Being.' WHERE figure_id = 66 AND text = 'This most beautiful system of the sun, planets, and comets, could only proceed from the counsel and dominion of an intelligent and powerful Being.';
UPDATE quotes SET source = 'Cited in David Brewster, Memoirs of the Life, Writings and Discoveries of Sir Isaac Newton (1855)', text = 'I do not know what I may appear to the world; but to myself I seem to have been only like a boy playing on the sea-shore, and diverting myself in now and then finding a smoother pebble or a prettier shell than ordinary, whilst the great ocean of truth lay all undiscovered before me.' WHERE figure_id = 66 AND text = 'I do not know what I may appear to the world, but to myself I seem to have been only like a boy playing on the seashore.';
UPDATE quotes SET source = 'The Principia: Mathematical Principles of Natural Philosophy, General Scholium (1713)', text = 'He governs all things, and knows all things that are or can be done.' WHERE figure_id = 66 AND text = 'God governs all things, and knows all that is or can be done.';
UPDATE quotes SET source = 'Pensées, Fragment 148 (Lafuma), published 1670', text = 'There was once in man a true happiness of which there now remain to him only the mark and empty trace… But these are all inadequate, because the infinite abyss can only be filled by an infinite and immutable object, that is to say, only by God Himself.' WHERE figure_id = 67 AND text = 'There is a God-shaped vacuum in the heart of each man which cannot be satisfied by any created thing, but only by God.';
UPDATE quotes SET source = 'Pensées, Fragment 423 (Lafuma)', text = 'The heart has its reasons, which reason does not know.' WHERE figure_id = 67 AND text = 'The heart has its reasons which reason knows nothing of.';
UPDATE quotes SET source = 'Pensées, Fragment 136 (Lafuma)', text = 'All the unhappiness of men arises from one single fact, that they cannot stay quietly in their own chamber.' WHERE figure_id = 67 AND text = 'All of humanity''s problems stem from man''s inability to sit quietly in a room alone.';
UPDATE quotes SET source = 'Pensées, Fragment 418 (Lafuma)', text = 'If you gain, you gain all; if you lose, you lose nothing. Wager, then, without hesitation that He is.' WHERE figure_id = 67 AND text = 'If you gain, you gain all; if you lose, you lose nothing. Wager, then, without hesitation that He is.';
UPDATE quotes SET source = 'Pensées, Fragment 149 (Lafuma)', text = 'There is enough light for those who only desire to see, and enough obscurity for those who have a contrary disposition.' WHERE figure_id = 67 AND text = 'In faith there is enough light for those who want to believe and enough shadows to blind those who don''t.';
UPDATE quotes SET source = 'Pensées, Fragment 200 (Lafuma)', text = 'Man is but a reed, the most feeble thing in nature; but he is a thinking reed.' WHERE figure_id = 67 AND text = 'Man is but a reed, the most feeble thing in nature; but he is a thinking reed.';
UPDATE quotes SET source = 'Pensées, Fragment 671 (Lafuma)', text = 'Do you wish people to believe good of you? Don''t speak.' WHERE figure_id = 67 AND text = 'Do you wish people to think well of you? Don''t speak well of yourself.';
