UPDATE quotes SET source = 'Pensées, Fragment 192 (Lafuma)', text = 'The knowledge of God without that of man''s misery causes pride. The knowledge of man''s misery without that of God causes despair.' WHERE figure_id = 67 AND text = 'The knowledge of God without that of man''s misery causes pride. The knowledge of man''s misery without that of God causes despair.';
UPDATE quotes SET source = 'Mere Christianity, Book II, Chapter 3 (1952)', text = 'God cannot give us a happiness and peace apart from Himself, because it is not there. There is no such thing.' WHERE figure_id = 68 AND text = 'God cannot give us a happiness and peace apart from Himself, because it is not there. There is no such thing.';
UPDATE quotes SET source = 'The Weight of Glory (1941)', text = 'Indeed, if we consider the unblushing promises of reward and the staggering nature of the rewards promised in the Gospels, it would seem that Our Lord finds our desires, not too strong, but too weak.' WHERE figure_id = 68 AND text = 'If we consider the unblushing promises of reward and the staggering nature of the rewards promised in the Gospels, it would seem that Our Lord finds our desires not too strong, but too weak.';
UPDATE quotes SET source = 'God in the Dock (1970)', text = 'Christianity is a statement which, if false, is of no importance, and, if true, of infinite importance. The one thing it cannot be is moderately important.' WHERE figure_id = 68 AND text = 'Christianity, if false, is of no importance, and if true, of infinite importance. The only thing it cannot be is moderately important.';
UPDATE quotes SET source = 'The Four Loves, Chapter 6 (1960)', text = 'To love at all is to be vulnerable. Love anything, and your heart will certainly be wrung and possibly be broken.' WHERE figure_id = 68 AND text = 'To love at all is to be vulnerable. Love anything and your heart will be wrung and possibly broken.';
UPDATE quotes SET source = 'Surprised by Joy, Chapter 14 (1955)', text = 'I gave in, and admitted that God was God, and knelt and prayed: perhaps, that night, the most dejected and reluctant convert in all England.' WHERE figure_id = 68 AND text = 'I gave in, and admitted that God was God, and knelt and prayed: perhaps, that night, the most dejected and reluctant convert in all England.';
UPDATE quotes SET source = 'The Screwtape Letters, Letter 29 (1942)', text = 'Courage is not simply one of the virtues, but the form of every virtue at the testing point.' WHERE figure_id = 68 AND text = 'Courage is not simply one of the virtues, but the form of every virtue at the testing point.';
UPDATE quotes SET source = 'Mere Christianity, Book III, Chapter 10 (1952)', text = 'If I find in myself a desire which no experience in this world can satisfy, the most probable explanation is that I was made for another world.' WHERE figure_id = 68 AND text = 'If I find in myself a desire which no experience in this world can satisfy, the most probable explanation is that I was made for another world.';
UPDATE quotes SET source = 'What''s Wrong with the World, Part I, Chapter 5 (1910)', text = 'The Christian ideal has not been tried and found wanting. It has been found difficult; and left untried.' WHERE figure_id = 69 AND text = 'The Christian ideal has not been tried and found wanting; it has been found difficult and left untried.';
UPDATE quotes SET source = 'Autobiography (1936)', text = 'The object of opening the mind, as of opening the mouth, is to shut it again on something solid.' WHERE figure_id = 69 AND text = 'The object of opening the mind, as of opening the mouth, is to shut it again on something solid.';
