UPDATE quotes SET source = 'Essays, Of Beauty (1625)', text = 'Virtue is like a rich stone, best plain set.' WHERE figure_id = 70 AND text = 'Virtue is like a rich stone, best plain set.';
UPDATE quotes SET source = 'Letter to the Grand Duchess Christina (1615)', text = 'I would say here something that was heard from an ecclesiastic of the most eminent degree: "That the intention of the Holy Ghost is to teach us how one goes to heaven, not how heaven goes."' WHERE figure_id = 71 AND text = 'The intention of the Holy Ghost is to teach us how one goes to heaven, not how heaven goes.';
UPDATE quotes SET source = 'Letter to the Grand Duchess Christina (1615)', text = 'This granted, and it being true that two truths cannot contradict one another, it is the function of expositors to seek out the true senses of scriptural texts.' WHERE figure_id = 71 AND text = 'Two truths cannot contradict one another: let us investigate natural phenomena boldly.';
UPDATE quotes SET source = 'The Assayer (Il Saggiatore, 1623)', text = 'Philosophy is written in this grand book, the universe, which stands continually open to our gaze… It is written in the language of mathematics.' WHERE figure_id = 71 AND text = 'This grand book of the universe is written in the language of mathematics.';
UPDATE quotes SET source = 'Letter to the Grand Duchess Christina (1615)', text = 'The holy Bible and the phenomena of nature proceed alike from the divine Word, the former as the dictate of the Holy Ghost and the latter as the observant executrix of God''s commands.' WHERE figure_id = 71 AND text = 'Holy Scripture and nature both proceed from the Divine Word.';
UPDATE quotes SET source = 'Cited in Max Caspar, Kepler (1959)', text = 'Since we astronomers are priests of the highest God in regard to the book of nature, it befits us to be thoughtful, not of the glory of our minds, but rather, above all else, of the glory of God.' WHERE figure_id = 72 AND text = 'Since we astronomers are priests of the highest God in regard to the book of nature, we must not think about the fame of our own minds, but above all else of the glory of God.';
