UPDATE quotes SET source = 'Cited in Francis Wayland, A Memoir of the Life and Labors of the Rev. Adoniram Judson (1853)', text = 'Had it not been for the consolations of religion, and an assured conviction that every additional trial was ordered by infinite love and mercy, I must have sunk under my accumulated sufferings.' WHERE figure_id = 88 AND text = 'If I had not felt certain that every additional trial was ordered by infinite love and mercy, I could not have survived my accumulated sufferings.';
